replace('tests/conformance/ghidra/psp-fixture.mjs', '/** Observations from Ghidra, not an echo of the requested profile. */', '''/** Independent GNU fields for the pinned PSPSDK fixture, not REA's parser. */
export function parsePspReadelfAbi(text) {
  const field = (expression, label) => {
    const matches = [...text.matchAll(expression)];
    assert.equal(matches.length, 1, `Missing or ambiguous PSP readelf ${label}`);
    return matches[0][1].trim();
  };
  const width = (name) => {
    const bits = Number(field(new RegExp(`^${name} size:\\\\s*(\\\\d+)\\\\s*$`, "gmu"), name));
    assert.ok(bits === 0 || bits === 32, `Unverified PSP ${name} width`);
    return bits === 32 ? 1 : 0;
  };
  const isaLevel = Number(field(/^ISA:\\s*MIPS(\\d+)\\s*$/gmu, "ISA"));
  assert.equal(field(/^FP ABI:\\s*(.+)$/gmu, "FP ABI"), "Hard float (single precision)");
  assert.equal(field(/^ISA Extension:\\s*(.+)$/gmu, "ISA extension"), "None");
  assert.equal(field(/^ASEs:\\s*\\n[ \\t]*(.+)$/gmu, "ASEs"), "None");
  const abi = {
    version: Number(field(/^MIPS ABI Flags Version:\\s*(\\d+)\\s*$/gmu, "ABI version")),
    isaLevel, isaRevision: 0,
    gprSize: width("GPR"), cpr1Size: width("CPR1"), cpr2Size: width("CPR2"),
    fpAbi: 2, isaExtension: 0, ases: 0,
    flags1: Number.parseInt(field(/^FLAGS 1:\\s*([\\da-f]+)\\s*$/gmu, "flags1"), 16),
    flags2: Number.parseInt(field(/^FLAGS 2:\\s*([\\da-f]+)\\s*$/gmu, "flags2"), 16),
  };
  assert.deepEqual(abi, {
    version: 0, isaLevel: 2, isaRevision: 0,
    gprSize: 1, cpr1Size: 1, cpr2Size: 0, fpAbi: 2,
    isaExtension: 0, ases: 0, flags1: 1, flags2: 0,
  }, "PSPSDK ABI declaration differs from independently inspected build intent");
  return abi;
}

/** Observations from Ghidra, not an echo of the requested profile. */''')
